def is_simple_power(x, n):
    """Returns True if x is a simple power of n (i.e., n**k == x for some integer k >= 0)."""
    # Handle special base cases
    if n == 0:
        return x in (0, 1)
    if n == 1:
        return x == 1

    # Iterate through exponents until n**k >= x
    k = 0
    while True:
        power = n ** k
        if power == x:
            return True
        if power > x:
            return False
        k += 1

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    if n < 2:
        return []

    primes = []
    for num in range(2, n):
        is_prime = True
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
    return primes

def sort_array(arr):
    """
    In this Kata, you have to sort an array of non-negative integers according to
    number of ones in their binary representation in ascending order.
    For similar number of ones, sort based on decimal value.

    It must be implemented like this:
    >>> sort_array([1, 5, 2, 3, 4]) == [1, 2, 3, 4, 5]
    >>> sort_array([-2, -3, -4, -5, -6]) == [-6, -5, -4, -3, -2]
    >>> sort_array([1, 0, 2, 3, 4]) == [0, 1, 2, 3, 4]
    """
    def key_func(x):
        if x < 0:
            # Negative numbers: sort ascending by value
            return (0, x)
        # Non-negative: sort by binary representation length, then by value
        return (len(bin(x)) - 2, x)  # strip '0b' prefix (2 chars)
    return sorted(arr, key=key_func)
